content:
﻿.wishlist-page { min-height: 75vh; padding-bottom: 120px; background: #fff; color: #203a30; }
.wishlist-header { background: #fff; }
.wishlist-header > div { padding-bottom: 20px; }
.wishlist-back { display: inline-flex; gap: 8px; align-items: center; min-height: 44px; margin-bottom: 12px; color: #899087; font-size: 11px; }
.wishlist-heading-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.wishlist-title { display: flex; align-items: center; gap: 12px; font-size: clamp(28px, 4vw, 40px); font-weight: 500; letter-spacing: -.05em; line-height: 1.2; }
.wishlist-title > span { display: inline-flex; align-items: center; justify-content: center; min-width: 25px; height: 25px; padding-inline: 7px; border: 1px solid #dfe4da; border-radius: 50%; color: #6d7e63; font-size: 11px; font-weight: 500; letter-spacing: 0; }
.wishlist-shop-link { display: inline-flex; gap: 12px; min-height: 44px; align-items: center; flex-shrink: 0; font-size: 12px; color: #62705a; }
.wishlist-shop-link:hover { color: #183c30; }
.wishlist-content { padding-top: 10px; }
.wishlist-products { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 32px 24px; }
.wishlist-products > article { border: 0; border-radius: 0; box-shadow: none; background: transparent; }
.wishlist-products > article:hover { box-shadow: none; }
.wishlist-products > article > div:first-child { border: 0; border-radius: 5px; background: #f5f4f0; aspect-ratio: 4 / 5; }
.wishlist-products > article > div:first-child img { padding: 0; }
.wishlist-products > article > div:last-child { padding: 18px 0 0; }
.wishlist-products h3 { min-height: auto; font-size: 15px; font-weight: 500; line-height: 1.5; letter-spacing: -.02em; }
.wishlist-products .text-red-600 { color: #233d30; }
.wishlist-products .font-extrabold { font-weight: 600; }
.wishlist-products .bg-red-500 { background: #fffffff0; border: 1px solid #e3e6dd; color: #56684a; font-weight: 500; border-radius: 3px; }
.wishlist-products article > div:last-child > a { background: transparent; border-radius: 0; padding-inline: 0; border-bottom: 1px solid #dce2d5; font-weight: 500; }
.wishlist-products article > div:last-child > a > span:last-child { background: transparent; color: #526448; }
.wishlist-products article:hover > div:last-child > a { background: transparent; border-color: #526448; }
.wishlist-products-single { display: block; max-width: 980px; }
.wishlist-products-single > article { display: grid; grid-template-columns: 1.2fr 1fr; gap: 48px; align-items: center; }
.wishlist-products-single > article > div:first-child { aspect-ratio: 1; }
.wishlist-products-single > article > div:last-child { padding: 20px 0; }
.wishlist-products-single h3 { font-size: 25px; line-height: 1.45; letter-spacing: -.035em; }
.wishlist-products-single article > div:last-child > div.mt-auto { margin-top: 12px; }
.wishlist-products-single article > div:last-child > a { margin-top: 28px; background: #203e30; border: 0; color: #fff; padding: 0 18px; border-radius: 4px; min-height: 50px; }
.wishlist-products-single article > div:last-child > a > span:last-child { color: white; }
.wishlist-products-single article:hover > div:last-child > a { background: #35563e; }
.wishlist-empty > div:first-child { background: #f3f5ee; color: #718263; border-radius: 50%; }
.wishlist-page :where(a, button):focus-visible { outline: 2px solid #65834e; outline-offset: 4px; }
@media (max-width: 767px) {
  .wishlist-products { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 28px 14px; }
  .wishlist-products-single { display: block; }
  .wishlist-products-single > article { grid-template-columns: minmax(0, 1fr); gap: 0; }
  .wishlist-products-single > article > div:first-child { aspect-ratio: 6 / 5; }
  .wishlist-products-single > article > div:last-child { padding: 22px 2px 0; }
  .wishlist-products-single h3 { font-size: 21px; max-width: 440px; }
  .wishlist-products-single article > div:last-child > a { margin-top: 20px; }
}
@media (max-width: 400px) {
  .wishlist-heading-row { align-items: flex-start; }
  .wishlist-shop-link { font-size: 10px; gap: 7px; min-height: 36px; }
  .wishlist-title { font-size: 27px; gap: 8px; }
  .wishlist-heading-row p { max-width: 220px; font-size: 11px; }
  .wishlist-products h3 { font-size: 13px; }
  .wishlist-products-single h3 { font-size: 20px; }
}
@media (prefers-reduced-motion: reduce) { .wishlist-page *, .wishlist-page *::before, .wishlist-page *::after { transition: none !important; animation: none !important; } }
